def find_max_coffin_width(a: float, b: float, l: float) -> Optional[float]:
    """
    Find the maximum width w of a coffin (rectangle l x w) that can pass through
    an L-shaped corridor with arm widths a and b.

    Returns None if no such coffin exists (My poor head =() case).
    """
    # Check if the coffin is too long to pass (length exceeds sum of corridor widths)
    if l > a + b:
        return None

    # If coffin length is less than or equal to minimum of a and b, 
    # we can just slide it through without rotation
    if l <= min(a, b):
        return l

    # Define the formula for width at angle theta:
    # w(θ) = a*s + b*c - l*(s + c) where s = sin(θ), c = cos(θ)
    def width_at_angle(theta: float) -> float:
        s = math.sin(theta)
        c = math.cos(theta)
        return a * s + b * c - l * (s + c)

    # Ensure w must be positive (non-negative width required per problem)
    # Also, width can't exceed length per problem statement (w <= l)
    def feasible_width(theta: float) -> Optional[float]:
        w = width_at_angle(theta)
        if w > 0:
            return min(w, l)
        return None

    # Binary search for the maximum width over angles [0, pi/2]
    # The critical region is near pi/2, where we get good corridor alignment
    best_width = 0.0
    best_theta = 0.0

    # Check upper bound first
    s, c = 1.0, 1e-9
    w = a * s + b * c - l * (s + c)
    if w > 0 and w > best_width:
        best_width = min(w, l)
        best_theta = math.pi/2

    # Refine search around optimal angles by checking key points and using optimization
    # The optimal angle typically satisfies: cos(theta)/sin(theta) = b/a
    # Or by direct numerical optimization

    sample_angles = [math.pi/2, 1.5, 1.4, 1.3, 1.2, 1.1, 1.0, 0.9, 0.8, 0.7]
    for theta in sample_angles:
        if theta <= math.pi/2:
            result = feasible_width(theta)
            if result is not None:
                if result > best_width:
                    best_width = result
                    best_theta = theta

    # Do a refinement search around best_theta found
    if best_width > 0:
        # Use golden section search or ternary search for better precision
        lo, hi = 0.0, math.pi/2
        for _ in range(100):
            m1 = lo + (hi - lo) * 0.333
            m2 = lo + (hi - lo) * 0.667

            for theta in [m1, m2, 0.01, 0.1, 0.5]:
                if 0 <= theta <= math.pi/2:
                    result = feasible_width(theta)
                    if result is not None:
                        if result > best_width:
                            best_width = result
                            best_theta = theta
        # Grid search refinement
        step = 0.001
        theta = 0.0
        while theta <= math.pi/2:
            result = feasible_width(theta)
            if result is not None:
                if result > best_width:
                    best_width = result
            theta += step
        theta = math.pi/2
        result = feasible_width(theta)
        if result is not None and result > best_width:
            best_width = result

    # Final check at boundaries
    theta = 0.0
    result = feasible_width(0.0)
    if result is not None and result > best_width:
        best_width = result

    if best_width <= 0:
        return None

    # Even if we found a positive width, ensure it meets the problem constraint w <= l
    if best_width > l:
        best_width = l

    # Check that a coffin with this width actually fits
    # For l <= a and l <= b, we can simply have w = l
    if l <= a and l <= b:
        return l

    return best_width


