    for i in range(m):
        v, u, w = edges[i]
        total_edge_weight += w

        edge_node = n + i + 1
        add_edge(source, edge_node, w)  # Edge node from source with capacity w
        add_edge(edge_node, v, float('inf'))  # Edge node to vertex v (infinity)
        add_edge(edge_node, u, float('inf'))  # Edge node to vertex u (infinity)

    for i in range(1, n + 1):
        add_edge(i, sink, a[i-1])  # Vertex to sink with capacity = vertex weight

    # Dinic's algorithm for max flow

    def bfs_dinic(s, t, n_nodes, g):
        level = [-1] * n_nodes
        level[s] = 0
        queue = [s]
        while queue:
            u = queue.pop(0)
            for v, cap, _ in g[u]:
                if cap > 0 and level[v] < 0:
                    level[v] = level[u] + 1
                    queue.append(v)
