                if pushed > 0:
                    g[v][i][1] -= pushed
                    g[m][rev][1] += pushed
                    return pushed
        return 0

    def dfs_dinic_recursive(s, t, f, n_nodes, g, level, ptr):
        if s == t or f == 0:
            return f
        for i in range(ptr[s], len(g[s])):
