def is_axis_square(matrix, r, c, k):
    # Check border is all 1s
    for i in range(k + 1):
        if matrix[r][c + i] != '1':
            return False
        if matrix[r + k - i][c + i] != '1':
            return False
        if matrix[r + i][c + k - i] != '1':
            return False
        if matrix[r + i][c] != '1':
            return False

    # Check no foreign 1s touch the border
    for i in range(r-1, r + k):
        for j in range(c-1, c + k):
            if matrix[i][j] == '1' and not (r <= i < r + k and c <= j < c + k):
                return False

    return True

def is_diagonal_square(matrix, r, c, s):
    # Border cells for diagonal square centered at (r, c) with radius s
    # Cells where max(|i-r|, |j-c|) == s or min(|i-r|+|j-c|) == s

    # The diagonal square in grid coords has 4 sides
    # Top diagonal: from (r-s, c) to (r, c-s)
    # Right vertical: from (r, c-s) to (r+s, c)
    # Bottom diagonal: from (r+s, c) to (r, c+s)
    # Left vertical: from (r, c+s) to (r-s, c)

    edges = [
        [(r - abs(k), c + abs(k)) for k in range(s + 1)],
        [(r + abs(k), c - abs(k)) for k in range(s + 1)],
        [(r + abs(k), c + abs(k)) for k in range(s + 1)],
        [(r - abs(k), c - abs(k)) for k in range(s + 1)]
    ]

    # Collect all unique border cells
    border_cells = set()
    for edge in edges:
        for cell in edge:
            border_cells.add(cell)

    # Check all border cells are 1
    for cr, cc in border_cells:
        if cr < 0 or cc < 0 or cr >= len(matrix) or cc >= len(matrix[0]):
            return False
        if matrix[cr][cc] != '1':
            return False

    return True

