        if bfs_check(i):
            w = edges[i][2]
            if w < min_ans:
                min_ans = w
                if len(best_ans_0) == 0 or pos == 1:
                    best_ans_1 = [i + 1]

    # Check 2 edges
    for i in range(m):
        for j in range(i + 1, m):
            if bfs_check(i) and bfs_check(j):
                w = edges[i][2] + edges[j][2]
                if w < min_ans:
                    min_ans = w
                    best_ans_2 = [i + 1, j + 1]

    if min_ans == float('inf'):
        return "-1"
    else:
        return f"{min_ans}\n{len(best_ans_2)}\n{' '.join(map(str, best_ans_2)) if best_ans_2 else ' '.join(map(str, best_ans_1))}"

class SegTree:
    def __init__(self, n):
        self.n = n
        self.cnt = [0] * (4 * (n + 2))  # count of ones (occupied)
        self.lazy = [-1] * (4 * (n + 2))  # lazy value (-1: none, 0: all free, 1: all occupied)

    def _push(self, node):
        if self.lazy[node] != -1:
            val = self.lazy[node]
            left = 2 * node
            right = left + 1

            # For a leaf (start == end), cnt is 1 if occupied, 0 if free
            # For an internal node with [start, end]
            # if val is 0 (free): count of 1s in range = 0
            # if val is 1 (occupied): count of 1s in range = end - start + 1
            self.cnt[left] = 0 if val == 0 else (self.cnt[2 * left] if self.lazy[left] != -1 else 0)
            # Actually let's reconstruct the size from a helper
            # We need to know the size of the range for each node

    def update_range(self, node, start, end, l, r, val):
        if val == -1 or start > end:
            return

        # Update current node
        if val == 0:  # Set all to free (0)
            self.cnt[node] = 0
            self.lazy[node] = 0
        else:  # val == 1, set all to occupied (1)
            self.cnt[node] = self.rsize(start, end)
            self.lazy[node] = 1

        if start > end:
            return

        if (l <= start) and (end <= r):
            if val == 0:
                self.cnt[node] = 0
            else:
                self.cnt[node] = self.rsize(start, end)
            self.lazy[node] = val
            return

        self.lazy[node] = -1
        mid = (start + end) // 2
        self.update_range(2 * node, start, mid, l, r, val)
        self.update_range(2 * node + 1, mid + 1, end, l, r, val)
        self.cnt[node] = self.cnt[2 * node] + self.cnt[2 * node + 1]

    def rsize(self, start, end):
        return end - start + 1

    def check_range_free(self, node, start, end, l, r):
        if start > end or self.cnt[node] > self.rsize(start, end):
            return False
        if l <= start and end <= r:
            return self.cnt[node] == 0
        self.lazy[node] = -1
        mid = (start + end) // 2
        return (self.check_range_free(2 * node, start, mid, l, r) and 
                self.check_range_free(2 * node + 1, mid + 1, end, l, r))


