def solution(input_str: str) -> str:
    # Clean the input
    input_str = input_str.strip()
    if not input_str:
        return "Lillebro"

    # Parse the grid
    lines = input_str.split('\n')
    grid = []
    for line in lines:
        parts = line.split()
        if parts:
            grid.append(parts)
        else:
            grid.append([])

    # Find all cells with chocolates
    chocolate_cells = []
    for row_idx, row in enumerate(grid):
        for col_idx, cell in enumerate(row):
            if cell == 'O':
                chocolate_cells.append((row_idx, col_idx))

    if not chocolate_cells:
        return "Lillebro"

    # Map (row, col) to index
    cell_to_idx = {}
    cells_list = []
    for idx, (r, c) in enumerate(chocolate_cells):
        cell_to_idx[(r, c)] = idx
        cells_list.append((r, c))

    num_cells = len(chocolate_cells)

    # Build adjacency graph for valid moves
    # In a hexagonal grid, adjacent cells can be:
    # - horizontal (same row, adjacent columns)
    # - diagonal (different rows with proper alignment)

    def get_neighbors(idx):
        r, c = cells_list[idx]
        neighbors = []

        # Check all other chocolate cells
        for j, (jr, jc) in enumerate(chocolate_cells):
            if idx == j:
                continue

            # Horizontal adjacency (same row)
            if r == jr and abs(c - jc) == 1:
                neighbors.append(j)
                continue

            # Diagonal/hexagonal neighbors
            # In hexagonal grid with staggered rows:
            # Cells in row r at col c can connect to:
            # - (r-1, c) or (r-1, c-1) depending on formatting
            # - (r+1, c) or (r+1, c+1) depending on formatting
            # Let's handle the common case

            # Pattern from examples suggests staggered rows
            # Odd rows shifted, even rows not shifted
            if abs(r - jr) == 1:
                if (r + jr) % 2 == 1:  # Staggered connection
                    if jc == c and 0 <= jc < len(grid[jr]):
                        neighbors.append(j)
                    elif jc == c and c < len(grid[jr]):
                        neighbors.append(j)

        return neighbors

    # Build full adjacency for used cells only
    # Simpler approach: adjacency is determined by the rules that allow lines
    # A line is valid if cells are consecutive and adjacent

    # Let's simplify: use BFS to find connected components
    def get_connected_component(start_idx: int, mask: int) -> Set[int]:
        """Find connected component starting from start_idx containing only positions in mask"""
        component = set()
        queue = [start_idx]
        while queue:
            curr = queue.pop(0)
            if curr in component:
                continue
            component.add(curr)

            # Find neighbors in current mask
            r, c = cells_list[curr]
            for other in chocolate_cells:
                or_, oc = other

                # Check if horizontally adjacent
                if r == or_ and abs(c - oc) == 1 and curr - len(chocolate_cells) < 0:
                    # Check other cell is in mask
                    if curr in mask:
                        component.add(other)

        return component

    # Simpler adjacency based only on what's in the actual grid
    def get_neighbors_simple(idx):
        r, c = cells_list[idx]
        neighbors = []

        for j, (jr, jc) in enumerate(chocolate_cells):
            if idx == j:
                continue

            # Same row, adjacent
            if r == jr and abs(c - jc) == 1:
                neighbors.append(j)

            # Staggered row connection pattern
            # Depends on hexagonal arrangement
            if abs(r - jr) == 1:
                if (r + jr) % 2 == 1:
                    if abs(c - jc) <= 1:
                        neighbors.append(j)

        return neighbors

    # Build adjacency graph
    adj = [get_neighbors_simple(idx) for idx in range(num_cells)]

    # Use memoization to determine winning/losing
    @lru_cache(maxsize=None)
    def is_winning(state_mask: int) -> bool:
        """Check if current player can win from this state"""
        # Find connected components in current state
        visited = set()
        components = []

        for idx in range(num_cells):
            if (state_mask >> idx) & 1 and idx not in visited:
                # BFS to find component
                component = []
                queue = [idx]
                visited.add(idx)

                while queue:
                    curr = queue.pop(0)
                    component.append(curr)

                    for neighbor in adj[curr]:
                        if ((state_mask >> neighbor) & 1) and neighbor not in visited:
                            visited.add(neighbor)
                            queue.append(neighbor)

                components.append(component)

        if not components:
            return False

        # Try each position in each component
        for component in components:
            for remove_idx in component:
                if not remove_idx:
                    continue

                # Try removing just this cell from its component
                new_state = state_mask & ~(1 << remove_idx)
                if not is_winning(new_state):
                    return True

        return False

    # Check if starting state is winning
    start_mask = 0
    for i, (r, c) in enumerate(chocolate_cells):
        start_mask |= (1 << i)

    # Karlsson goes first
    if is_winning(start_mask):
        return "Karlsson"
    return "Lillebro"


