from collections import deque

def bfs(start, n, adj):
    """BFS to find shortest distances from start to all other nodes"""
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == float('inf'):
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

def distance_matrix(n, adj):
    """Compute shortest distances between all pairs"""
    dist = [bfs(i, n, adj) for i in range(1, n + 1)]
    return dist

