    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    N, M, K = int(first_line[0]), int(first_line[1]), int(first_line[2])

    transformers = []
    for i in range(1, K+1):
        parts = lines[i].split()
        x, y, d, t, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
        transformers.append((x, y, d, t, e))

    # Precompute: for each position (r,c), which transformers are active there at time T=r+c
    # costs_at[r][c] = sum of energy costs of transformers at (r, c) that are active at time r+c
    costs_at = [[0] * M for _ in range(N)]

    for r in range(N):
        for c in range(M):
            T = r + c
            for x, y, d, t, e in transformers:
                if T >= t:
                    cycle = (T - t) % 4
                    if cycle == 0:
                        px, py = x, y
                    elif cycle == 1:
                        px, py = x + d, y - d
                    elif cycle == 2:
                        px, py = x + d, y
                    elif cycle == 3:
                        px, py = x, y + d
                    if px == r and py == c:
                        costs_at[r][c] += e

    # DP: dp[r][c] = minimum energy to reach (r, c)
    INF = 10**18
    dp = [[INF] * M for _ in range(N)]

    dp[0][0] = costs_at[0][0]

    # Fill diagonal from top-left to bottom-right in order of time = r+c
    for time in range(1, N + M - 1):
        max_r = min(time + 1, N)
        for r in range(max_r):
            c = time - r
            if c < 0:
                continue
            if c >= M:
                continue

            cell = costs_at[r][c]
            from_above = INF
            if r > 0:
                from_above = dp[r-1][c] + cell
            from_left = INF
            if c > 0:
                from_left = dp[r][c-1] + cell

            dp[r][c] = min(from_above, from_left)
            if from_above == INF and r == 0:
                dp[r][c] = from_left
            if from_left == INF and c == 0:
                dp[r][c] = from_above

    # Handle the bottom-right corner case
    time = N + M - 2
    r, c = N - 1, M - 1

    if r == 0 and c == 0:
        # Single cell case
        return str(costs_at[r][c])

    INF = 10**18
    from_above = INF
    if r > 0:
        from_above = dp[r-1][c] + costs_at[r][c]
    from_left = INF
    if c > 0:
        from_left = dp[r][c-1] + costs_at[r][c]

    result = INF if (from_above == INF and from_left == INF) else min(from_above, from_left)
    return str(result)

