    if n == 0:
        return str(ts)

    # Find optimal arrival time
    # Vasya should arrive when queue is guaranteed to be empty

    finish_times = []
    for arr in arrivals:
        start = max(arr, ts)
        for prev in finish_times:
            if start < prev:
                start = prev
        finish = start + t
        finish_times.append(finish)

    best = None

    # When no one arrived before office opens (Vasya first)
    if ts + t <= tf:
        best = ts

    # After each visitor's service
    for i in range(n):
        if i == n - 1:
            # Last visitor, queue empty after they finish
            after_finish = ts
            if after_finish + t <= tf:
                best = min(best, after_finish) if best else after_finish
        else:
            # Between visitor i finish and visitor i+1 arrive
            when_empty = finish_times[i]
            next_arrive = arrivals[i+1]
            for cand in range(when_empty, next_arrive):
                if cand + t <= tf:
                    if best is None or cand < best:
                        best = cand
