def get_primes(x):
    """Return set of prime factors of x"""
    primes = set()
    if x <= 1:
        return primes
    temp = x
    d = 2
    while d * d <= temp:
        if temp % d == 0:
            primes.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        primes.add(temp)
    return primes

