MOD = 10**9 + 7

def solution(X_str):
    X_str = X_str.strip()
    if not X_str:
        return "0"

    # For small numbers, compute directly
    if int(X_str) <= 10**6:
        X = int(X_str)
        total = 0
        for n in range(1, X + 1):
            s = sorted(str(n))
            total = (total + int(''.join(s))) % MOD
        return str(total)

    L = len(X_str)
    digits = [int(d) for d in X_str]

    @lru_cache(maxsize=None)
    def dp(pos, tight, digit_counts):
        if pos == L:
            result = sum(c * i for c, i in zip(digit_counts, range(10))) % MOD
            return result

        total = 0
        limit = int(X_str[pos]) if tight else 9

        for d in range(limit + 1):
            new_tight = tight and (d == limit)
            new_counts = list(digit_counts)
            new_counts[d] += 1
            total = (total + dp(pos + 1, new_tight, tuple(new_counts))) % MOD

        return total

    result = dp(0, True, tuple([0] * 10))
    return str(result)


