from collections import deque

def solution(input_str):
    input_str = input_str.strip()
    if not input_str:
        return '0\n'

    n = int(input_str)

    if n == 0:
        return '0\n'

    # BFS to find minimum operations to reduce n to 0
    # At each step, we can subtract any digit that appears in the current number
    queue = deque([(n, 0)])
    visited = {n}

    while queue:
        current, dist = queue.popleft()

        if current == 0:
            return str(dist) + '\n'

        # Get distinct digits present in current number
        s = str(current)
        distinct_digits = set(s)

        for digit in distinct_digits:
            d = int(digit)
            # Skip subtracting 0 as it doesn't reduce the number
            if d == 0:
                continue

            new_val = current - d
            if new_val not in visited:
                visited.add(new_val)
                queue.append((new_val, dist + 1))

    return '-1\n'
